package myfirstmodule.research;
public final class ActiveSimulationHtml { private ActiveSimulationHtml() {} public static final String VALUE = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>MicroExplore \u2014 Active simulation experiments</title>\n<style nonce=\"__NONCE__\">\n*{box-sizing:border-box}body{margin:0;background:white;color:#243247;font:16px/1.5 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:24px}h1{font-size:30px;margin:8px 0}h2{font-size:21px}a{color:#315f96}header{border-bottom:1px solid #dde3ea;padding-bottom:16px}.tag{color:#666;font-size:14px}section{margin:20px 0;padding:18px;border:1px solid #dbe2eb;border-radius:5px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}label{display:block;font-size:14px;font-weight:600}input,select,button{font:inherit;padding:9px;border:1px solid #aab9cb;border-radius:4px;max-width:100%}input,select{width:100%}button{background:#365c8d;color:white;cursor:pointer;margin:12px 8px 0 0}button:disabled{opacity:.55;cursor:default}.muted{color:#5d697a}#error{color:#9b2020}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:8px;text-align:left;border-bottom:1px solid #e2e6ed;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.5 ui-monospace,monospace}.scroll{overflow-x:auto}.bar{height:7px;background:#e9edf2;margin:3px 0}.bar span{display:block;height:100%;background:#426c9d}.bar:nth-child(2) span{background:#409a87}.key{font-weight:600}.observation{background:#f5f8fc;padding:12px}@media(max-width:650px){main{padding:12px}.grid{grid-template-columns:1fr}h1{font-size:25px}section{padding:12px}td,th{padding:6px}button{width:100%}}\n</style></head><body><main>\n<header><a href=\"/active-simulation-lab/evidence\" id=\"return\">\u2190 Circuit Diagnosis Simulator</a><p class=\"tag\">AI ELECTRONICS LAB \u00b7 ADVANCED SIMULATION</p><h1>Estimate circuit parameters from readings</h1><p>Set a virtual circuit, run the suggested measurements, then compare the estimated and configured parameter values.</p></header>\n<section><h2>1. Set the virtual circuit</h2><div class=\"grid\"><label>Electronic system<select id=\"system\"></select></label><label>Virtual load profile<select id=\"profile\"><option value=\"nominal\">Declared linear model</option><option value=\"current_limit\">LED: current limit</option><option value=\"soft_limit\">LED: soft limiting</option><option value=\"load_leakage\">LED: additional load</option></select></label></div><div class=\"grid\" id=\"parameters\"></div><p class=\"tag\">The estimator receives the captured readings and compares its estimates with the circuit settings.</p><button id=\"start\" disabled>Start virtual device</button><button id=\"repeat\" hidden>Repeat this experiment</button><button id=\"newNoise\" hidden>Try a different noise sample</button><details><summary>Seed settings</summary><p class=\"muted\">The simulator assigns and records seeds automatically. Enter values to reproduce a saved run.</p><div class=\"grid\"><label>Circuit seed<input id=\"seed\" type=\"number\" min=\"0\" max=\"2147483647\" step=\"1\" placeholder=\"Automatic\"></label><label>Noise seed<input id=\"noiseSeed\" type=\"number\" min=\"0\" max=\"2147483647\" step=\"1\" placeholder=\"Automatic\"></label></div><p id=\"usedSeeds\" class=\"muted\"></p></details></section>\n<p id=\"error\" role=\"alert\"></p><p id=\"status\" role=\"status\">No experiment has run.</p>\n<section id=\"experiment\" hidden><h2>2. AI suggests; you execute</h2><p id=\"reason\"></p><pre id=\"controls\"></pre><button id=\"capture\">Execute suggested virtual capture</button><p class=\"tag\">Four captures identify parameters. One optional extra capture checks the fitted model. Suggestions never count as observations.</p><div id=\"explanation\" class=\"observation\"></div></section>\n<section id=\"results\" hidden><h2>3. Compare and interpret</h2><p id=\"assessment\"></p><p id=\"uncertainty\" class=\"muted\"></p><div class=\"scroll\"><table><thead><tr><th>Parameter</th><th>Configured</th><th>Estimated</th><th>Candidate interval (95% target)</th></tr></thead><tbody id=\"comparison\"></tbody></table></div><p id=\"modelcheck\"></p><h3>Shared research fault candidates</h3><p id=\"fusion\"></p><div class=\"scroll\"><table><thead><tr><th>Candidate</th><th>Research model score</th></tr></thead><tbody id=\"candidates\"></tbody></table></div><p class=\"tag\">New four-mechanism simulation task, not a passed49-class production replacement. An abnormal parameter is not a unique component diagnosis. Unknown and mixed faults remain possible.</p><details><summary>Original stable ranking (preserved)</summary><pre id=\"original\"></pre></details></section>\n<section id=\"record\" hidden><h2>Executed captures</h2><div class=\"scroll\"><table><thead><tr><th>#</th><th>Action</th><th>Actual virtual readings</th></tr></thead><tbody id=\"history\"></tbody></table></div></section>\n</main><script nonce=\"__NONCE__\">\n'use strict';const $=id=>document.getElementById(id);let catalog,state,busy=false,csrf=\"__CSRF__\",deadline=0,lastSetup=null;const names={ANALOG_ADC:'ADC',DIGITAL_INPUT:'Digital Input',LED_GPIO:'LED / GPIO',I2C_SENSOR:'I2C',UART_DEVICE:'UART',PWM_MOTOR_SERVO:'PWM'};\nfunction randomSeed(previous){let value;do{value=crypto.getRandomValues(new Uint32Array(1))[0]>>>1;}while(value===previous);return value;}\nconst fmt=v=>typeof v==='number'?Number(v.toPrecision(6)).toString():String(v);function text(id,s){$(id).textContent=s}function row(parent,values){const tr=document.createElement('tr');values.forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td)});$(parent).append(tr)}\nasync function responseJson(response){\n const sessionUnavailable=[401,403,404,419].includes(response.status);\n let value;\n try{value=JSON.parse(await response.text());}\n catch{\n  const error=Error(sessionUnavailable?'This session is unavailable. Sign in again and start a new experiment.':'The simulation service returned an unavailable response. Please try again.');\n  error.status=response.status;throw error;\n }\n if(!response.ok){\n  const error=Error(sessionUnavailable?'This session is unavailable. Sign in again and start a new experiment.':typeof value?.detail==='string'?value.detail:'The simulation service could not complete this request. Check your settings and try again.');\n  error.status=response.status;throw error;\n }\n return value;\n}\nasync function call(route,data){const r=await fetch(route,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-Active-CSRF':csrf}:{},body:data?JSON.stringify(data):undefined,credentials:'same-origin'});return responseJson(r);}\nfunction configure(){const system=$('system').value,s=catalog.systems[system];$('return').href='/active-simulation-lab/evidence?system='+encodeURIComponent(system);$('parameters').replaceChildren();s.parameters.forEach((p,i)=>{const l=document.createElement('label');l.textContent=p.replaceAll('_',' ');const input=document.createElement('input');input.type='number';input.step='any';input.min=s.lower[i];input.max=s.upper[i];input.value=(s.lower[i]+s.upper[i])/2;input.dataset.parameter=p;l.append(input);$('parameters').append(l)});$('profile').disabled=system!=='LED_GPIO';if($('profile').disabled)$('profile').value='nominal'}\nfunction render(v){state=v;deadline=Date.now()+v.expires_in_seconds*1000;text('status',`${names[v.system]} \u00b7 ${v.revision} executed capture(s) \u00b7 research session expires in ${v.expires_in_seconds}s`);for(const id of ['experiment','results','record'])$(id).hidden=false;text('reason',v.proposal?v.proposal.reason:'Capture budget complete. Review the comparison or start another device.');text('controls',v.proposal?JSON.stringify(v.proposal.controls,null,2):'No further capture proposed.');$('capture').disabled=!v.proposal;text('assessment',`${v.assessment.status} \u00b7 observable rank ${v.assessment.data_rank}/${catalog.systems[v.system].parameters.length} \u00b7 normalized residual ${fmt(v.assessment.normalized_residual_rms??0)}`);text('uncertainty',v.uncertainty.status+(v.uncertainty.intervals?' \u2014 calibrated reference task only; not a guarantee for arbitrary configured parameters.':' \u2014 no supported interval is issued.'));text('explanation',Object.entries(v.explanation).map(([k,x])=>(k[0].toUpperCase()+k.slice(1)).replaceAll('_',' ')+': '+x).join(' '));$('comparison').replaceChildren();for(const r of v.comparison)row('comparison',[r.parameter,fmt(r.configured),fmt(r.estimated),r.interval?r.interval.map(fmt).join(' to '):'Not enough evidence']);text('fusion',`${v.fusion.status}. Remaining candidates: ${v.fusion.candidate_set.join(', ')}.`);$('candidates').replaceChildren();v.fusion.fault_ranking.forEach(r=>row('candidates',[r.fault,(100*r.probability).toFixed(1)+'%']));text('original',v.original_stable_ranking.map(r=>`${r.fault}: ${(100*r.probability).toFixed(1)}%`).join('\\n'));text('modelcheck',v.model_check?'Extra model check: '+v.model_check.status:'No extra model-check capture has run.');$('history').replaceChildren();v.history.forEach((r,i)=>row('history',[i+1,r.action_code,r.values.map(fmt).join(', ')]))}\nfunction invalidate(message){state=null;deadline=0;$('capture').disabled=true;for(const id of ['experiment','results','record'])$(id).hidden=true;text('status',message);text('error','');text('controls','');}\nwindow.addEventListener('pageshow',e=>{if(e.persisted)invalidate('Returned page: start a new virtual device to obtain fresh authorization.');});\ndocument.addEventListener('visibilitychange',()=>{if(!document.hidden&&deadline&&Date.now()>=deadline)invalidate('Research session expired. Start a new virtual device; no old capture will be reused.');});\nsetInterval(()=>{if(deadline&&Date.now()>=deadline)invalidate('Research session expired. Start a new virtual device; no old capture will be reused.');},1000);\nasync function perform(fn){if(busy)return;busy=true;for(const id of ['start','repeat','newNoise','capture'])$(id).disabled=true;text('error','');try{render(await fn())}catch(e){if([401,403,404,409,419].includes(e.status))invalidate('Session ended or capture state changed. Start a new virtual device.');text('error',e.message)}finally{busy=false;$('start').disabled=!catalog;$('repeat').disabled=$('newNoise').disabled=!lastSetup;$('capture').disabled=!state?.proposal}}\nfunction startExperiment(mode){return perform(async()=>{\n    const fields=[...$('parameters').querySelectorAll('input')];\n    let setup;\n    if(mode==='start'){\n        if(!['seed','noiseSeed'].every(id=>$(id).checkValidity()))throw Error('Enter a whole-number seed from 0 to 2147483647, or leave it blank.');\n        if(fields.some(field=>field.value===''||!field.checkValidity()))throw Error('Enter each circuit parameter within its allowed range.');\n        const seed=$('seed').value===''?randomSeed():Number($('seed').value);\n        setup={system:$('system').value,seed,noise_seed:$('noiseSeed').value===''?seed:Number($('noiseSeed').value),profile:$('profile').value,parameters:fields.map(field=>Number(field.value))};\n    }else{\n        setup={...lastSetup};if(mode==='noise')setup.noise_seed=randomSeed(setup.noise_seed);\n        $('system').value=setup.system;configure();$('profile').value=setup.profile;\n        $('parameters').querySelectorAll('input').forEach((field,i)=>{field.value=setup.parameters[i];});\n        $('seed').value='';$('noiseSeed').value='';\n    }\n    invalidate('Starting a new virtual device.');const fresh=await call('renew');csrf=fresh.csrf;\n    const result=await call('start',setup);lastSetup={...setup,...result.reproducibility};\n    text('usedSeeds','Last experiment: circuit seed '+lastSetup.seed+', noise seed '+lastSetup.noise_seed+'.');$('repeat').hidden=$('newNoise').hidden=false;\n    return result;\n});}\n$('start').onclick=()=>startExperiment('start');$('repeat').onclick=()=>startExperiment('repeat');$('newNoise').onclick=()=>startExperiment('noise');\n$('capture').onclick=()=>{if(!state?.proposal)return;perform(()=>call('capture',{session_id:state.session_id,revision:state.revision,token:state.token,action_code:state.proposal.action_code}))};$('system').onchange=()=>{configure();invalidate('Settings changed. Start a new virtual device to use them.');};\ncall('catalog').then(v=>{catalog=v;for(const [code,name] of Object.entries(names))if(Object.hasOwn(v.systems,code))$('system').add(new Option(name,code));const system=new URLSearchParams(window.location.search).get('system');if(Object.hasOwn(v.systems,system))$('system').value=system;configure();$('start').disabled=false;}).catch(e=>text('error',e.message));\n</script></body></html>\n"; }
